const COLOR_CSS=":host{color:var(--ink);background:transparent;--accent:var(--tabbit-card-primary);--accent-alt:var(--tabbit-card-secondary);--ink:var(--tabbit-card-foreground);--muted:var(--tabbit-card-muted);--paper:var(--tabbit-card-background);--on-accent:var(--tabbit-card-on-primary);--panel-paper:var(--tabbit-card-background);--button-paper:var(--tabbit-card-background);--line:color-mix(in srgb,var(--tabbit-card-foreground) 18%,transparent);--soft:color-mix(in srgb,var(--tabbit-card-primary) 12%,var(--tabbit-card-background));--danger:var(--tabbit-card-foreground);--design-accent:var(--accent);--design-accentAlt:var(--accent-alt);--design-ink:var(--ink);--design-muted:var(--muted);--design-surface:var(--paper);--design-panel:var(--panel-paper);--design-stroke:var(--line);--design-onAccent:var(--on-accent);}.card{background:transparent}.card:has(>.infra-panel)>:not(.infra-panel){visibility:hidden}";
const CSS=".card{box-sizing:border-box;height:100%;padding:8px;color:var(--ink);font:12px/1.35 system-ui,-apple-system,\"PingFang SC\",\"Microsoft YaHei\",sans-serif;overflow:hidden;min-width:0;min-height:0}\n.card *{box-sizing:border-box}\n.card[data-size=\"3x6\"]{padding:10px}\n.card[data-size=\"6x6\"]{padding:12px;font-size:13px}\n.card button{font:inherit;color:var(--ink);background:none;border:0;padding:0;margin:0;cursor:pointer;-webkit-tap-highlight-color:transparent}\n.card button:focus-visible,.card input:focus-visible{outline:2px solid var(--accent);outline-offset:1px}\n.card button:disabled{opacity:.55;cursor:default}\n.view{height:100%;display:flex;flex-direction:column;gap:6px;min-height:0;min-width:0}\n\n.top{display:flex;flex-wrap:wrap;align-items:center;gap:6px;flex:none;min-width:0}\n.tabs{display:flex;background:var(--soft);border-radius:999px;padding:2px;gap:1px;flex:none}\n.tab{padding:2px 8px;min-height:22px;border-radius:999px;font-size:11px;white-space:nowrap;color:var(--ink)}\n.card .tab.on{background:var(--accent);color:var(--on-accent);font-weight:600}\n.card .add{margin-left:auto;min-width:26px;height:26px;padding:0 10px;border-radius:999px;background:var(--accent);color:var(--on-accent);font-weight:600;white-space:nowrap}\n.nav{display:flex;align-items:center;gap:4px;min-width:0;flex:1 1 auto}\n.card[data-size=\"3x3\"] .nav,.card[data-size=\"3x6\"] .nav{order:3;flex:1 1 100%}\n.range{flex:1;text-align:center;font-weight:600;white-space:nowrap;min-width:0}\n.card .nb{width:24px;height:24px;flex:none;border-radius:50%;border:1px solid var(--line);display:inline-flex;align-items:center;justify-content:center;font-size:15px;line-height:1;background:var(--panel-paper)}\n.card .nb.back{width:auto;padding:0 8px;border-radius:999px;font-size:10px;white-space:nowrap}\n.now{flex:none;font-size:10px;line-height:1;color:var(--accent);border:1px solid var(--accent);border-radius:999px;padding:4px 7px;white-space:nowrap}\n.notice{flex:none;font-size:11px;background:var(--soft);border-left:3px solid var(--accent-alt);border-radius:4px;padding:3px 6px}\n\n.body{flex:1;min-height:0;min-width:0;display:flex;flex-direction:column;gap:6px}\n.card[data-size=\"6x3\"] .body{flex-direction:row}\n.strip{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:3px;flex:none}\n.card[data-size=\"6x3\"] .strip{grid-template-columns:none;grid-template-rows:repeat(7,minmax(0,1fr));width:74px}\n.card .dc{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:1px;min-width:0;min-height:0;padding:3px 0;border-radius:8px;border:1px solid transparent;background:var(--soft);line-height:1.1}\n.dc .w{font-size:10px;color:var(--muted)}\n.dc .d{font-size:14px;font-weight:700}\n.dc .n{font-size:10px;min-height:11px;color:var(--accent);font-weight:700}\n.card .dc.today{border-color:var(--accent)}\n.card .dc.sel{background:var(--accent);color:var(--on-accent)}\n.dc.sel .w,.dc.sel .n,.dc.sel .d{color:var(--on-accent)}\n.dc.fin .n::before{content:\"\u2713\"}\n.card[data-size=\"6x3\"] .dc{flex-direction:row;justify-content:space-between;padding:0 6px;gap:3px}\n.card[data-size=\"6x3\"] .dc .d{font-size:12px}\n.card[data-size=\"6x3\"] .dc .n{min-width:8px;min-height:0;text-align:right}\n.card[data-size=\"6x6\"] .dc{padding:6px 0;gap:3px}\n.card[data-size=\"6x6\"] .dc .d{font-size:18px}\n.card[data-size=\"6x6\"] .dc .w{font-size:11px}\n\n.list{flex:1;min-height:0;min-width:0;overflow-y:auto;overflow-x:hidden;display:flex;flex-direction:column;gap:6px;padding-right:2px}\n.grp{display:flex;flex-direction:column;gap:5px;flex:none}\n.gh{display:flex;align-items:baseline;gap:6px;font-size:11px;color:var(--muted)}\n.gh b{color:var(--ink);font-size:12px}\n.gh em{font-style:normal;background:var(--accent);color:var(--on-accent);border-radius:999px;padding:0 6px;font-size:10px}\n.hint{flex:none;text-align:left;border:1px dashed var(--line);border-radius:8px;padding:4px 8px;font-size:11px;background:var(--soft)}\n.empty{margin:auto;text-align:center;color:var(--muted);display:flex;flex-direction:column;gap:8px;align-items:center;padding:6px;min-width:0}\n.empty p{margin:0}\n.empty .add{margin:0}\n\n\n.row{display:grid;grid-template-columns:minmax(0,1fr);gap:6px;background:var(--panel-paper);border:1px solid var(--line);border-radius:10px;padding:6px 8px 7px;min-width:0}\n.card[data-size=\"6x3\"] .row,.card[data-size=\"6x6\"] .row{grid-template-columns:minmax(0,1fr) auto;align-items:center;column-gap:8px}\n.card .main{text-align:left;min-width:0;display:flex;flex-direction:column;gap:2px;align-items:stretch}\n.row.done .main{opacity:.7}\n.ttl{font-weight:600;font-size:13px;line-height:1.3;overflow:hidden;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow-wrap:anywhere}\n.meta{display:flex;flex-wrap:wrap;align-items:center;gap:2px 6px;font-size:11px;color:var(--muted);min-width:0}\n.plat{max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:var(--ink);background:var(--soft);border-radius:999px;padding:0 7px}\n.plat.none{color:var(--muted);background:none;padding:0}\n.tag{white-space:nowrap}\n.tag.warn{color:var(--ink);font-weight:700}\n.chips{display:flex;gap:3px;min-width:0}\n.card .chip{flex:1 1 0;min-width:0;height:24px;padding:0 1px;border:1px solid var(--line);border-radius:7px;font-size:11px;white-space:nowrap;background:transparent;color:var(--ink)}\n.card .chip.on{background:var(--accent);border-color:var(--accent);color:var(--on-accent);font-weight:600}\n.card .chip.pub{border-style:dashed}\n.card .chip.pub.on{background:var(--accent-alt);border-color:var(--accent-alt);border-style:solid;color:var(--on-accent)}\n.card[data-size=\"6x3\"] .chip,.card[data-size=\"6x6\"] .chip{flex:none;padding:0 6px}\n.bar{grid-column:1/-1;display:grid;grid-template-columns:repeat(4,1fr);gap:3px;height:3px}\n.bar i{background:var(--line);border-radius:2px}\n.bar i.on{background:var(--accent)}\n\n.form .fh{display:flex;align-items:center;gap:8px;flex:none;font-size:13px}\n.fbody{flex:1;min-height:0;min-width:0;overflow-y:auto;overflow-x:hidden;display:grid;grid-template-columns:minmax(0,1fr);gap:8px;align-content:start;padding:2px 2px 4px}\n.card[data-size=\"6x3\"] .fbody,.card[data-size=\"6x6\"] .fbody{grid-template-columns:repeat(2,minmax(0,1fr));column-gap:12px}\n.fld{display:flex;flex-direction:column;gap:4px;min-width:0}\n.fld.full{grid-column:1/-1}\n.lb{font-size:11px;color:var(--muted)}\n.card .in{width:100%;min-width:0;height:30px;border:1px solid var(--line);border-radius:8px;background:var(--panel-paper);color:var(--ink);padding:0 8px;font:inherit}\n.dr{display:flex;align-items:center;gap:4px;min-width:0}\n.dr .in{flex:1 1 0;padding:0 4px}\n.wdl{flex:none;font-size:11px;color:var(--muted)}\n.pcs{display:flex;flex-wrap:wrap;gap:4px}\n.card .pc{height:22px;padding:0 8px;border:1px solid var(--line);border-radius:999px;font-size:11px;background:var(--panel-paper)}\n.card .pc.on{background:var(--soft);border-color:var(--accent);font-weight:600}\n.cks{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:2px 8px}\n.ck{display:flex;align-items:center;gap:6px;min-height:26px;font-size:12px;min-width:0}\n.ck input{width:16px;height:16px;flex:none;margin:0;accent-color:var(--accent)}\n.ff{display:flex;flex-wrap:wrap;align-items:center;gap:6px;flex:none}\n.err{flex:1 1 100%;font-size:11px;font-weight:600}\n.card .save{flex:1;height:30px;border-radius:8px;background:var(--accent);color:var(--on-accent);font-weight:600}\n.card .del{height:30px;padding:0 12px;border:1px solid var(--line);border-radius:8px;background:var(--panel-paper);white-space:nowrap}\n.card .del.sure{border-color:var(--accent-alt);font-weight:700}\n";
const WD=['日','一','二','三','四','五','六'];
const KEYS=[['copy','文案'],['image','配图'],['cover','封面'],['proof','校对']];
function fD(d){
  return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
}
function pD(s){
  const m=/^(\d{4})-(\d{2})-(\d{2})$/.exec(s||'');
  if(!m)return null;
  const d=new Date(+m[1],+m[2]-1,+m[3]);
  return fD(d)===s?d:null;
}
function addD(s,n){
  const d=pD(s);
  if(!d)return s;
  d.setDate(d.getDate()+n);
  return fD(d);
}
function monOf(s){
  const d=pD(s);
  if(!d)return s;
  d.setDate(d.getDate()-((d.getDay()+6)%7));
  return fD(d);
}
function wdOf(s){
  const d=pD(s);
  return d?WD[d.getDay()]:'';
}
function md(s,y){
  const d=pD(s);
  if(!d)return '未定日期';
  const base=(d.getMonth()+1)+'/'+d.getDate();
  return y&&String(d.getFullYear())!==y?d.getFullYear()+'/'+base:base;
}
function doneN(p){
  const c=p.checks||{};
  return KEYS.filter(k=>c[k[0]]).length;
}
function cmp(a,b){
  return (a.date||'').localeCompare(b.date||'')||(a.createdAt||0)-(b.createdAt||0);
}
function groups(list){
  const out=[];
  let cur=null;
  list.forEach(p=>{
    if(!cur||cur.date!==p.date){cur={date:p.date,items:[]};out.push(cur);}
    cur.items.push(p);
  });
  return out;
}

function mount(ctx){
  const {root,el,state,ui,update,commit,redraw,uid,day,size}=ctx;
  const today=day();
  const yr=today.slice(0,4);
  const posts=(Array.isArray(state.posts)?state.posts:[]).slice().sort(cmp);
  if(!ui.tab)ui.tab='cal';
  if(!ui.weekStart)ui.weekStart=monOf(today);
  const small=size==='3x3';
  const effDay=small?null:ui.day;
  const kids=a=>a.filter(Boolean);
  let listEl=null;
  let formEl=null;

  function note(msg){ui.notice=msg;redraw();}
  function fail(){note('保存失败，请稍后重试');}
  function patch(id,fn){
    ui.notice='';
    return update(s=>({...s,posts:(Array.isArray(s.posts)?s.posts:[]).map(p=>p.id===id?fn(p):p)})).catch(fail);
  }
  function toggleCheck(id,k){
    patch(id,p=>({...p,checks:{...(p.checks||{}),[k]:!(p.checks||{})[k]}}));
  }
  function togglePub(id){
    patch(id,p=>p.published?{...p,published:false,publishedAt:null}:{...p,published:true,publishedAt:day()});
  }

  function openForm(p){
    ui.notice='';
    const inWeek=today>=ui.weekStart&&today<=addD(ui.weekStart,6);
    const defDate=ui.tab==='cal'?(effDay||(inWeek?today:ui.weekStart)):today;
    const c=(p&&p.checks)||{};
    ui.fscroll=0;
    ui.form=p?{id:p.id,err:'',confirmDel:false,saving:false,draft:{
      title:p.title||'',platform:p.platform||'',date:p.date||today,
      published:!!p.published,publishedAt:p.publishedAt||null,
      checks:{copy:!!c.copy,image:!!c.image,cover:!!c.cover,proof:!!c.proof}}}
    :{id:null,err:'',confirmDel:false,saving:false,draft:{
      title:'',platform:'',date:defDate,published:false,publishedAt:null,
      checks:{copy:false,image:false,cover:false,proof:false}}};
    redraw();
  }

  function saveForm(){
    const f=ui.form;
    if(!f||f.saving)return;
    const d=f.draft;
    const title=(d.title||'').trim();
    if(!title){f.err='请先填写标题';redraw();return;}
    if(!pD(d.date)){f.err='请选择计划发布日';redraw();return;}
    f.saving=true;
    f.err='';
    const id=f.id||uid();
    const rec={title,platform:(d.platform||'').trim(),date:d.date,checks:{...d.checks}};
    const next={...ui,form:null,notice:''};
    if(ui.tab==='cal'){next.weekStart=monOf(d.date);next.day=null;}
    commit(s=>{
      const list=Array.isArray(s.posts)?s.posts:[];
      const old=list.find(p=>p.id===id);
      const pub=!!d.published;
      const base=old||{id,createdAt:Date.now()};
      const item={...base,...rec,published:pub,publishedAt:pub?((old&&old.publishedAt)||d.publishedAt||day()):null};
      return {...s,posts:old?list.map(p=>p.id===id?item:p):list.concat([item])};
    },next).catch(()=>{f.saving=false;f.err='保存失败，请重试';redraw();});
  }

  function delForm(){
    const f=ui.form;
    if(!f||!f.id||f.saving)return;
    if(!f.confirmDel){f.confirmDel=true;redraw();return;}
    f.saving=true;
    commit(s=>({...s,posts:(Array.isArray(s.posts)?s.posts:[]).filter(p=>p.id!==f.id)}),{...ui,form:null,notice:''})
      .catch(()=>{f.saving=false;f.err='删除失败，请重试';redraw();});
  }


  function chip(label,on,onClick,cls){
    return el('button',{type:'button',class:'chip'+(on?' on':'')+(cls?' '+cls:''),'aria-pressed':on?'true':'false',onclick:onClick},(on&&!small?'✓':'')+label);
  }

  function row(p){
    const n=doneN(p);
    const c=p.checks||{};
    const over=!p.published&&p.date<today;
    const meta=el('span',{class:'meta'},...kids([
      el('span',{class:p.platform?'plat':'plat none'},p.platform||'未填平台'),
      el('span',{class:'prog'},'进度 '+n+'/4'),
      over?el('span',{class:'tag warn'},'⚠ 逾期'):null,
      p.published?el('span',{class:'tag ok'},'✓ 已发'):null
    ]));
    const main=el('button',{type:'button',class:'main','aria-label':'编辑：'+p.title,onclick:()=>openForm(p)},
      el('span',{class:'ttl'},p.title||'(无标题)'),meta);
    const chips=el('div',{class:'chips'},
      ...KEYS.map(k=>chip(k[1],!!c[k[0]],()=>toggleCheck(p.id,k[0]))),
      chip('发布',!!p.published,()=>togglePub(p.id),'pub'));
    const bar=el('div',{class:'bar'},...[0,1,2,3].map(i=>el('i',{class:i<n?'on':''})));
    return el('div',{class:'row'+(p.published?' done':'')},main,chips,bar);
  }

  function group(g){
    return el('div',{class:'grp'},
      el('div',{class:'gh'},...kids([
        el('b',{},'周'+wdOf(g.date)),
        el('span',{},md(g.date,yr)),
        g.date===today?el('em',{},'今天'):null
      ])),
      ...g.items.map(row));
  }

  function tabBtn(key,label,count){
    return el('button',{type:'button',role:'tab','aria-selected':ui.tab===key?'true':'false',class:'tab'+(ui.tab===key?' on':''),
      onclick:()=>{ui.tab=key;ui.notice='';redraw();}},label+(count!=null&&!small?' '+count:''));
  }

  function nav(){
    const ws=ui.weekStart;
    const cur=monOf(today);
    const go=n=>{ui.weekStart=addD(ws,n*7);ui.day=null;redraw();};
    return el('div',{class:'nav'},...kids([
      el('button',{type:'button',class:'nb','aria-label':'上一周',onclick:()=>go(-1)},'‹'),
      el('span',{class:'range'},md(ws,yr)+' – '+md(addD(ws,6),yr)),
      el('button',{type:'button',class:'nb','aria-label':'下一周',onclick:()=>go(1)},'›'),
      ws===cur?el('span',{class:'now'},'本周')
        :el('button',{type:'button',class:'nb back',onclick:()=>{ui.weekStart=cur;ui.day=null;redraw();}},small?'今':'回本周')
    ]));
  }

  function strip(){
    const cells=[];
    for(let i=0;i<7;i++){
      const d=addD(ui.weekStart,i);
      const items=posts.filter(p=>p.date===d);
      const fin=items.length>0&&items.every(p=>p.published);
      const sel=ui.day===d;
      cells.push(el('button',{type:'button',
        class:'dc'+(sel?' sel':'')+(d===today?' today':'')+(items.length?' has':'')+(fin?' fin':''),
        'aria-pressed':sel?'true':'false',
        'aria-label':'周'+wdOf(d)+' '+md(d,yr)+'，'+items.length+'篇',
        onclick:()=>{ui.day=sel?null:d;redraw();}},
        el('span',{class:'w'},(size==='3x6'?'':'周')+wdOf(d)),
        el('span',{class:'d'},String(pD(d).getDate())),
        el('span',{class:'n'},items.length?String(items.length):'')));
    }
    return el('div',{class:'strip'},...cells);
  }

  function addBtn(label){
    return el('button',{type:'button',class:'add','aria-label':'新建图文',onclick:()=>openForm(null)},label);
  }

  function listView(){
    let items;
    if(ui.tab==='pending')items=posts.filter(p=>!p.published);
    else if(ui.tab==='done')items=posts.filter(p=>p.published).reverse();
    else{
      const end=addD(ui.weekStart,6);
      items=posts.filter(p=>p.date>=ui.weekStart&&p.date<=end&&(!effDay||p.date===effDay));
    }
    const parts=[];
    if(ui.tab==='cal'){
      const od=posts.filter(p=>!p.published&&p.date<ui.weekStart&&p.date<today).length;
      if(od>0)parts.push(el('button',{type:'button',class:'hint',onclick:()=>{ui.tab='pending';redraw();}},'⚠ 更早还有 '+od+' 篇逾期未发，去看看 ›'));
    }
    if(!items.length){
      let msg;
      if(ui.tab==='pending')msg='没有待发的图文';
      else if(ui.tab==='done')msg='还没有发布过的图文。在图文行里点「发布」就会留在这里。';
      else if(!posts.length)msg='还没有图文安排。填好标题、平台和计划发布日，就能排进日历。';
      else msg=effDay?'这天还没有安排':'这周还没有安排';
      parts.push(el('div',{class:'empty'},...kids([el('p',{},msg),ui.tab==='done'?null:addBtn('＋ 新建图文')])));
    }else{
      groups(items).forEach(g=>parts.push(group(g)));
    }
    const key=ui.tab+'|'+ui.weekStart+'|'+effDay;
    if(ui.scrollKey!==key){ui.scrollKey=key;ui.scroll=0;}
    listEl=el('div',{class:'list',onscroll:e=>{ui.scroll=e.target.scrollTop;}},...parts);
    return listEl;
  }

  function mainView(){
    const np=posts.filter(p=>!p.published).length;
    const nd=posts.length-np;
    const top=el('div',{class:'top'},...kids([
      el('div',{class:'tabs',role:'tablist'},tabBtn('cal','周历'),tabBtn('pending','待发',np),tabBtn('done','已发',nd)),
      ui.tab==='cal'?nav():null,
      addBtn(small?'＋':'＋ 新建')
    ]));
    const body=el('div',{class:'body'},...kids([ui.tab==='cal'&&!small?strip():null,listView()]));
    return el('div',{class:'view'},...kids([
      top,
      ui.notice?el('div',{class:'notice',role:'alert'},'⚠ '+ui.notice):null,
      body
    ]));
  }


  function formView(){
    const f=ui.form;
    const d=f.draft;
    const onEnter=e=>{if(e.key==='Enter')saveForm();};
    const titleIn=el('input',{type:'text',class:'in','aria-label':'标题',value:d.title,placeholder:'图文标题',
      oninput:e=>{d.title=e.target.value;},onkeydown:onEnter});
    const platIn=el('input',{type:'text',class:'in','aria-label':'平台',value:d.platform,placeholder:'如 公众号、小红书',
      oninput:e=>{d.platform=e.target.value;},onkeydown:onEnter});
    const used=posts.map(p=>(p.platform||'').trim()).filter((x,i,a)=>x&&a.indexOf(x)===i).slice(0,10);
    const pcs=used.length?el('div',{class:'pcs'},...used.map(x=>
      el('button',{type:'button',class:'pc'+((d.platform||'').trim()===x?' on':''),onclick:()=>{d.platform=x;redraw();}},x))):null;
    const wdLab=el('span',{class:'wdl'},d.date?'周'+wdOf(d.date):'');
    const dateIn=el('input',{type:'date',class:'in','aria-label':'计划发布日',value:d.date||'',
      oninput:e=>{d.date=e.target.value;wdLab.textContent=d.date?'周'+wdOf(d.date):'';}});
    const shift=n=>{d.date=addD(pD(d.date)?d.date:today,n);redraw();};
    const dateRow=el('div',{class:'dr'},
      el('button',{type:'button',class:'nb','aria-label':'提前一天',onclick:()=>shift(-1)},'‹'),
      dateIn,
      el('button',{type:'button',class:'nb','aria-label':'推迟一天',onclick:()=>shift(1)},'›'),
      wdLab);
    const checks=el('div',{class:'cks'},...KEYS.map(k=>
